  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1120;
      --panel: rgba(15, 23, 42, 0.9);
      --panel-border: rgba(148, 163, 184, 0.18);
      --text: #e2e8f0;
      --muted: #94a3b8;
      --accent: #38bdf8;
      --accent-strong: #0ea5e9;
      --error: #fda4af;
      --error-border: rgba(251, 113, 133, 0.85);
      --success: #86efac;
      --shadow: 0 24px 80px rgba(2, 6, 23, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(56, 189, 248, 0.12), transparent 30%),
        linear-gradient(160deg, #020617 0%, #0f172a 45%, #111827 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      letter-spacing: 0.01em;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 14px;
      background: rgba(15, 23, 42, 0.9);
      color: var(--text);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.15);
      transform: translateY(-1px);
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .error-message {
      min-height: 1.2em;
      color: var(--error);
      font-size: 0.92rem;
    }

    .form-field.invalid input {
      border-color: var(--error-border);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    .submit-button {
      border: 0;
      border-radius: 14px;
      padding: 15px 18px;
      font-size: 1rem;
      font-weight: 700;
      color: #082f49;
      background: linear-gradient(135deg, #7dd3fc 0%, #38bdf8 50%, #0ea5e9 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 16px 36px rgba(14, 165, 233, 0.28);
    }

    .submit-button:hover,
    .submit-button:focus-visible {
      transform: translateY(-1px);
      filter: brightness(1.03);
    }

    .submit-button:active {
      transform: translateY(0);
    }

    .status-message {
      min-height: 1.2em;
      margin: 0;
      font-size: 0.95rem;
      color: var(--success);
    }
  </style>
</head>
<body>
  <section class="support-card" aria-labelledby="support-title">
    <h1 id="support-title">Contact Support</h1>
    <p class="intro">Send us your details and our support team will get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required>
        <p class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required>
        <p class="error-message" aria-live="polite"></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input id="phone-number" name="phone" type="tel" autocomplete="tel" placeholder="+1 555-123-4567">
        <p class="helper-text">Optional. Use digits, spaces, dashes, or parentheses, for example: +1 555-123-4567.</p>
        <p class="error-message" aria-live="polite"></p>
      </div>

      <button class="submit-button" type="submit">Submit</button>
      <p class="status-message" id="status-message" aria-live="polite"></p>
    </form>
  </section>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("status-message");

    const fieldConfigs = [
      {
        input: document.getElementById("full-name"),
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("email-address"),
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
        }
      },
      {
        input: document.getElementById("phone-number"),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }

          const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
          if (!phonePattern.test(trimmed)) {
            return "Enter a valid phone number.";
          }

          return "";
        }
      }
    ];

    function setFieldState(input, message) {
      const formField = input.closest(".form-field");
      const errorMessage = formField.querySelector(".error-message");
      const isInvalid = Boolean(message);

      formField.classList.toggle("invalid", isInvalid);
      input.setAttribute("aria-invalid", String(isInvalid));
      errorMessage.textContent = message;
    }

    function validateField(config) {
      const message = config.validate(config.input.value);
      setFieldState(config.input, message);
      return !message;
    }

    fieldConfigs.forEach((config) => {
      config.input.addEventListener("blur", () => validateField(config));
      config.input.addEventListener("input", () => {
        if (config.input.closest(".form-field").classList.contains("invalid")) {
          validateField(config);
        }
        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = fieldConfigs.every((config) => validateField(config));

      if (!isValid) {
        statusMessage.textContent = "";
        return;
      }

      statusMessage.textContent = "Your request has been submitted.";
      form.reset();
      fieldConfigs.forEach((config) => setFieldState(config.input, ""));
    });
  </script>
</body>
</html>
