           }

           const phonePattern = /^\+?[0-9()\-\s]{7,20}$/;
           if (!phonePattern.test(trimmed)) {
             return "Enter a valid phone number.";
           }

           return "";
         }
       }
     ];

     function setFieldState(input, message) {
       const formField = input.closest(".form-field");
       const errorMessage = formField.querySelector(".error-message");
       const isInvalid = Boolean(message);

       formField.classList.toggle("invalid", isInvalid);
       input.setAttribute("aria-invalid", String(isInvalid));
       errorMessage.textContent = message;
     }

     function validateField(config) {
       const message = config.validate(config.input.value);
       setFieldState(config.input, message);
       return !message;
     }

     fieldConfigs.forEach((config) => {
       config.input.addEventListener("blur", () => validateField(config));
